import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { resolve } from 'node:path'

const EXPECTED_HEAD = '47f943859bef60e4160492346772ded9b24f765a'
const root = resolve(fileURLToPath(new URL('..', import.meta.url)))
const fixtureRoot = resolve(process.argv[3] ?? root)
const fixture = JSON.parse(await readFile(resolve(fixtureRoot, 'fixtures', `dsh-${EXPECTED_HEAD}.json`), 'utf8')) as {
  head: string
  runtime: Record<string, { version: string, sha256: string }>
}
if (fixture.head !== EXPECTED_HEAD) {
  throw new Error(`official-head-smoke: fixture expected ${EXPECTED_HEAD}, got ${fixture.head}`)
}

const packageFiles: Record<string, string> = {
  '@deepseek-ai/cordis': 'node_modules/@deepseek-ai/cordis/lib/index.js',
  '@deepseek-ai/dsh-session': 'node_modules/@deepseek-ai/dsh-session/lib/index.js',
  '@deepseek-ai/dsh-llm': 'node_modules/@deepseek-ai/dsh-llm/lib/index.js',
  '@deepseek-ai/dsh-session-telemetry': 'node_modules/@deepseek-ai/dsh-session-telemetry/lib/index.js',
}
for (const [name, path] of Object.entries(packageFiles)) {
  const runtime = fixture.runtime[name]
  if (runtime === undefined) throw new Error(`official-head-smoke: fixture omits ${name}`)
  const manifest = JSON.parse(await readFile(resolve(root, 'node_modules', name, 'package.json'), 'utf8')) as { version: string }
  const bytes = await readFile(resolve(root, path))
  const digest = createHash('sha256').update(bytes).digest('hex')
  if (manifest.version !== runtime.version || digest !== runtime.sha256) {
    throw new Error(`official-head-smoke: pinned ${name} runtime does not match fixture`)
  }
}

const [{ Context }, sessionModule, llmModule, telemetryModule, Redactor] = await Promise.all([
  import('@deepseek-ai/cordis'),
  import('@deepseek-ai/dsh-session'),
  import('@deepseek-ai/dsh-llm'),
  import('@deepseek-ai/dsh-session-telemetry'),
  import(process.argv[2] ?? new URL('../lib/index.js', import.meta.url).href),
])
if (
  typeof Context !== 'function'
  || typeof sessionModule.default !== 'function'
  || typeof sessionModule.SessionId !== 'function'
  || typeof llmModule.createUserMessage !== 'function'
  || typeof telemetryModule.SessionTelemetryCoordinator !== 'function'
) {
  throw new Error('official-head-smoke: pinned runtime API surface changed')
}

const records: unknown[] = []
const backend = {
  emit: (record: unknown) => records.push(record),
  shutdown: async () => {},
}
const secret = `sk-${'officialhead1234567890'}`
const ctx = new Context()
await ctx.plugin(sessionModule.default)
await ctx.plugin(Redactor)
const telemetryFiber = await ctx.plugin({
  name: 'official-head-fixture-telemetry',
  inject: ['sessions'],
  apply: (inner: InstanceType<typeof Context>) => {
    new telemetryModule.SessionTelemetryCoordinator(inner, backend)
  },
})
const session = ctx.sessions.create(sessionModule.SessionId('official-head-redactor'))
session.append('user/message', llmModule.createUserMessage({
  content: [{ type: 'text', text: `credential ${secret}` }],
  source: { kind: 'user' },
}), { surfaceOp: 'append' })

const wire = JSON.stringify(records)
const canonical = JSON.stringify(session.events)
if (wire.includes(secret) || !wire.includes('[REDACTED]')) {
  throw new Error(`official-head-smoke: unsafe export ${wire}`)
}
if (!canonical.includes(secret) || canonical.includes('[REDACTED]')) {
  throw new Error(`official-head-smoke: canonical log changed ${canonical}`)
}
await telemetryFiber.dispose()
await ctx.fiber.dispose()
console.log(`official-head-smoke: PASS ${fixture.head}`)

