import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = resolve(fileURLToPath(new URL('..', import.meta.url)))
const tempRoot = resolve(root, '.tmp', 'packed-install')
const artifacts = resolve(tempRoot, 'artifacts')
const consumer = resolve(tempRoot, 'consumer')
const pnpmCli = process.env.npm_execpath
if (pnpmCli === undefined || pnpmCli.length === 0) throw new Error('packed-install-smoke: run through pnpm')
const runPnpm = (args, options = {}) => execFileSync(process.execPath, [pnpmCli, ...args], {
  cwd: options.cwd ?? root,
  env: options.env ?? process.env,
  stdio: 'inherit',
})

await rm(tempRoot, { recursive: true, force: true })
await mkdir(artifacts, { recursive: true })
await mkdir(consumer, { recursive: true })
try {
  runPnpm(['pack', '--pack-destination', artifacts])
  const manifest = JSON.parse(await readFile(resolve(root, 'package.json'), 'utf8'))
  const tarball = resolve(artifacts, `${manifest.name}-${manifest.version}.tgz`)
  await writeFile(resolve(consumer, 'package.json'), JSON.stringify({ private: true, type: 'module' }))
  runPnpm([
    'add', '--ignore-scripts', '--config.auto-install-peers=false', '--config.lockfile=false',
    tarball, '@deepseek-ai/cordis@4.0.1', '@deepseek-ai/dsh-session-telemetry@0.1.0-rc.6',
  ], { cwd: consumer })

  const packageRoot = resolve(consumer, 'node_modules', manifest.name)
  const installedManifest = JSON.parse(await readFile(resolve(packageRoot, 'package.json'), 'utf8'))
  if (installedManifest.private === true) throw new Error('packed-install-smoke: public package is unexpectedly private')
  if (installedManifest.publishConfig?.access !== 'public') {
    throw new Error('packed-install-smoke: public access metadata is missing')
  }
  execFileSync(process.execPath, ['--input-type=module', '--eval', [
    "import { Context } from '@deepseek-ai/cordis'",
    "import * as Redactor from 'dsh-telemetry-redactor'",
    "const secret = 'sk-' + 'packedinstall1234567890'",
    "const record = { channel: 'ops', time: 1, severity: 'error', attributes: { 'telemetry.op': 'agent-error' }, body: { authorization: secret } }",
    'const ctx = new Context()',
    'await ctx.plugin(Redactor)',
    "if (JSON.stringify(ctx.waterfall('session-telemetry/record', record, () => record)).includes(secret)) throw new Error('packed import leaked')",
  ].join(';')], { cwd: consumer, stdio: 'inherit' })

  runPnpm(['run', 'test:official-head', pathToFileURL(resolve(packageRoot, 'lib', 'index.js')).href, packageRoot])
  runPnpm(['run', 'test:official-patch', packageRoot])
  console.log(`packed-install-smoke: PASS ${dirname(tarball)}`)
} finally {
  await rm(tempRoot, { recursive: true, force: true })
}

