import { describe, expect, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import type { SessionTelemetryRecord } from '@deepseek-ai/dsh-session-telemetry'
import * as Redactor from '../src/index.ts'

const secret = (label: string) => `sk-${label}1234567890`

function record(body: unknown): SessionTelemetryRecord {
  return {
    channel: 'ledger',
    time: 1,
    severity: 'info',
    attributes: {
      'session.id': 'adversarial',
      'event.type': 'fixture/event',
      'event.seq': 1,
    },
    body,
  }
}

async function transform(body: unknown, config: Redactor.Config = {}): Promise<SessionTelemetryRecord> {
  const ctx = new Context()
  await ctx.plugin(Redactor, config)
  const input = record(body)
  return ctx.waterfall('session-telemetry/record', input, () => input)
}

describe('supported secret locations', () => {
  it('redacts key names, nested values, arrays, query parameters, headers, and error strings', async () => {
    const keySecret = secret('objectkey')
    const values = {
      [keySecret]: 'key itself carried the credential',
      nested: {
        password: 'plain-password',
        array: [
          `https://example.invalid/path?access_token=${secret('query')}&page=2`,
          `Authorization: Bearer ${secret('header')}`,
          `request failed: api_key=${secret('error')}`,
        ],
      },
    }

    const output = await transform(values)
    const wire = JSON.stringify(output)
    for (const value of [keySecret, 'plain-password', secret('query'), secret('header'), secret('error')]) {
      expect(wire).not.toContain(value)
    }
    expect(wire).toContain('[REDACTED]')
    expect(wire).toContain('page=2')
  })

  it('preserves official and common token telemetry fields', async () => {
    const metrics = {
      usage: {
        inputTokens: 11,
        outputTokens: 7,
        cacheReadTokens: 5,
        cacheWriteTokens: 3,
        reasoningTokens: 2,
      },
      tokenUsage: { input: 11, output: 7 },
      tokenCount: 18,
      totalTokens: 18,
      contextTokens: 128_000,
      contextTokenCount: 4_096,
      maxTokens: 8_192,
      prompt_tokens: 11,
      completion_tokens: 7,
      tokenizer: 'cl100k_base',
    }

    expect((await transform(metrics)).body).toEqual(metrics)
  })
})

describe('explicit negative boundaries', () => {
  it('does not claim to detect unlabelled opaque or encoded credentials', async () => {
    const unsupported = {
      opaque: 'zYxWvU9876543210',
      sample1: 'https://example.invalid/?access%5Ftoken%3DzYxWvU9876543210',
      sample2: 'Bearer short',
      sample3: 'Cookie: sid=zYxWvU9876543210',
    }

    expect((await transform(unsupported)).body).toEqual(unsupported)
  })

  it('rejects a replacement that itself matches a supported secret pattern', async () => {
    const ctx = new Context()
    const fiber = ctx.plugin(Redactor, { replacement: secret('replacement') })
    await expect(fiber.await()).rejects.toThrow('replacement')
  })
})

describe('hostile object behavior', () => {
  it('rejects accessors without invoking their getter', async () => {
    let reads = 0
    const body = Object.defineProperty({}, 'secret', {
      enumerable: true,
      get() {
        reads += 1
        return secret('getter')
      },
    })
    const ctx = new Context()
    await ctx.plugin(Redactor)
    const input = record(body)

    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('accessor')
    expect(reads).toBe(0)

    const array: unknown[] = []
    Object.defineProperty(array, '0', {
      enumerable: true,
      get() {
        reads += 1
        return secret('array-getter')
      },
    })
    const arrayRecord = record(array)
    expect(() => ctx.waterfall('session-telemetry/record', arrayRecord, () => arrayRecord)).toThrow('accessor')
    expect(reads).toBe(0)
  })

  it('rejects non-plain objects instead of silently changing their meaning', async () => {
    const ctx = new Context()
    await ctx.plugin(Redactor)
    const input = record({ when: new Date(0) })

    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('plain')
  })

  it('contains no proxy guarantee but propagates a throwing trap for coordinator containment', async () => {
    const ctx = new Context()
    await ctx.plugin(Redactor)
    const proxy = new Proxy({}, {
      getPrototypeOf() {
        throw new Error('proxy trap')
      },
    })
    const input = record(proxy)

    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('proxy trap')
  })

  it('rejects cycles and retains linear behavior for a large shallow record', async () => {
    const cyclic: Record<string, unknown> = {}
    cyclic.self = cyclic
    const ctx = new Context()
    await ctx.plugin(Redactor)
    const cyclicRecord = record(cyclic)
    expect(() => ctx.waterfall('session-telemetry/record', cyclicRecord, () => cyclicRecord)).toThrow('cycle')

    const size = 20_000
    const shallow = Object.fromEntries(Array.from({ length: size }, (_, index) => [`metric_${index}`, index]))
    const started = performance.now()
    const output = await transform(shallow)
    const elapsedMillis = performance.now() - started
    expect(Object.keys(output.body as object)).toHaveLength(size)
    expect(elapsedMillis).toBeLessThan(2_000)
  })

  it('rejects collisions created by redacting credential-bearing key names', async () => {
    const first = secret('collision-a')
    const second = secret('collision-b')
    const ctx = new Context()
    await ctx.plugin(Redactor)
    const input = record({ [first]: 1, [second]: 2 })

    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('collision')
  })
})

describe('listener composition boundary', () => {
  it('wraps ordinary listeners mounted before the redactor', async () => {
    const ctx = new Context()
    ctx.on('session-telemetry/record', (_candidate, next) => ({
      ...next(),
      body: { apiKey: secret('ordinary-listener') },
    }))
    await ctx.plugin(Redactor)
    const input = record({ safe: true })
    expect(JSON.stringify(ctx.waterfall('session-telemetry/record', input, () => input)))
      .not.toContain(secret('ordinary-listener'))
  })

  it('proves a more-outer prepended listener can bypass this rule', async () => {
    const ctx = new Context()
    await ctx.plugin(Redactor)
    const bypass = secret('outer-bypass')
    ctx.on('session-telemetry/record', () => record({ raw: bypass }), { prepend: true })
    const input = record({ safe: true })

    expect(JSON.stringify(ctx.waterfall('session-telemetry/record', input, () => input))).toContain(bypass)
  })
})

