import { Context } from '@deepseek-ai/cordis'
import Include from '@deepseek-ai/cordis-plugin-include'
import Loader from '@deepseek-ai/cordis-plugin-loader'
import SessionStore, { SessionId } from '@deepseek-ai/dsh-session'
import { createUserMessage } from '@deepseek-ai/dsh-llm'
import {
  SessionTelemetryCoordinator,
  type SessionTelemetryRecord,
  type SessionTelemetrySink,
} from '@deepseek-ai/dsh-session-telemetry'
import * as Redactor from '../src/index.ts'

const SECRET = `sk-${'loaderfixture1234567890'}`
let root: string | undefined
let context: Context | undefined

afterEach(async () => {
  await context?.fiber.dispose()
  context = undefined
  if (root !== undefined) await rm(root, { recursive: true, force: true })
  root = undefined
})

describe('real Loader and telemetry coordinator composition', () => {
  it('exports a redacted copy while the canonical session event retains the secret', async () => {
    root = await mkdtemp(join(tmpdir(), 'dsh-telemetry-redactor-'))
    const configPath = join(root, 'cordis.yml')
    await writeFile(configPath, [
      "- id: sessions",
      "  name: '@deepseek-ai/dsh-session'",
      "- id: telemetry-redactor",
      "  name: 'dsh-telemetry-redactor'",
      '  config:',
      "    replacement: '[WIRE-REDACTED]'",
      "- id: telemetry-backend",
      "  name: 'fixture-telemetry-backend'",
      '',
    ].join('\n'))

    const records: SessionTelemetryRecord[] = []
    const backend: SessionTelemetrySink = {
      emit: record => records.push(record),
      shutdown: async () => {},
    }
    const fixtureBackend = {
      name: 'fixture-telemetry-backend',
      inject: ['sessions'],
      apply: (ctx: Context) => void new SessionTelemetryCoordinator(ctx, backend),
    }

    const ctx = new Context()
    context = ctx
    ctx.baseUrl = pathToFileURL(root).href + '/'
    await ctx.plugin(Loader)
    ctx.loader.builtins.include = Include
    const modules = new Map<string, unknown>([
      ['@deepseek-ai/dsh-session', SessionStore],
      ['dsh-telemetry-redactor', Redactor],
      ['fixture-telemetry-backend', fixtureBackend],
    ])
    ctx.loader.internal = {
      version: 'v2',
      async import(specifier: string) {
        if (!modules.has(specifier)) throw new Error(`unexpected Loader import: ${specifier}`)
        return modules.get(specifier)
      },
    } as unknown as NonNullable<typeof ctx.loader.internal>
    await ctx.loader.create({
      name: 'cordis:include',
      config: { path: pathToFileURL(configPath).href },
    })
    await ctx.loader.await()

    const session = ctx.sessions.create(SessionId('redactor-loader'))
    session.append('user/message', createUserMessage({
      content: [{ type: 'text', text: `credential ${SECRET}` }],
      source: { kind: 'user' },
    }), { surfaceOp: 'append' })

    expect(JSON.stringify(records)).not.toContain(SECRET)
    expect(JSON.stringify(records)).toContain('[WIRE-REDACTED]')
    expect(JSON.stringify(session.events)).toContain(SECRET)
    expect(JSON.stringify(session.events)).not.toContain('[WIRE-REDACTED]')

    let tooDeep: Record<string, unknown> = { leaf: 'safe' }
    for (let index = 0; index < 70; index += 1) tooDeep = { child: tooDeep }
    const count = records.length
    const originalWarn = ctx.logger.warn
    const warnings: string[] = []
    ctx.logger.warn = (...args: unknown[]) => {
      warnings.push(args.map(String).join(' '))
    }
    ctx.emit('session/event', session, {
      type: 'fixture/deep',
      seq: 1,
      time: Date.now(),
      data: tooDeep,
      ignorable: true,
    } as never)
    expect(records).toHaveLength(count)
    expect(warnings).toHaveLength(1)
    expect(warnings[0]).toContain('maximum nesting depth')
    ctx.logger.warn = originalWarn
  })
})

