import { describe, expect, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import type { SessionTelemetryRecord } from '@deepseek-ai/dsh-session-telemetry'
import * as Redactor from '../src/index.ts'

const API_KEY = `sk-${'fixture1234567890'}`
const BEARER = 'fixtureBearerToken1234567890'
const ACCESS_TOKEN = 'fixtureAccessToken1234567890'

function fixture(): SessionTelemetryRecord {
  return {
    channel: 'ledger',
    time: 1_786_633_600_000,
    severity: 'info',
    attributes: {
      'session.id': 'fixture-session',
      'event.type': 'tool/result',
      'event.seq': 7,
    },
    body: {
      apiKey: API_KEY,
      nested: [{ Authorization: `Bearer ${BEARER}` }],
      command: `curl -H "Authorization: Bearer ${BEARER}" "https://example.invalid/?access_token=${ACCESS_TOKEN}"`,
      usage: { inputTokens: 321, output_tokens: 17 },
      tokenizer: 'cl100k_base',
    },
  }
}

async function mounted(config: Redactor.Config = {}): Promise<Context> {
  const ctx = new Context()
  await ctx.plugin(Redactor, config)
  return ctx
}

describe('telemetry export redaction', () => {
  it('recursively redacts sensitive keys and credential patterns without mutating the input', async () => {
    const ctx = await mounted({ replacement: '[SAFE]' })
    const input = fixture()
    const before = structuredClone(input)

    const output = ctx.waterfall('session-telemetry/record', input, () => input)
    const wire = JSON.stringify(output)

    expect(wire).not.toContain(API_KEY)
    expect(wire).not.toContain(BEARER)
    expect(wire).not.toContain(ACCESS_TOKEN)
    expect(wire).toContain('[SAFE]')
    expect(output.body).toMatchObject({
      apiKey: '[SAFE]',
      nested: [{ Authorization: '[SAFE]' }],
      usage: { inputTokens: 321, output_tokens: 17 },
      tokenizer: 'cl100k_base',
    })
    expect(input).toEqual(before)
  })

  it('redacts secret patterns in attributes and ops bodies too', async () => {
    const ctx = await mounted()
    const record: SessionTelemetryRecord = {
      channel: 'ops',
      time: 1,
      severity: 'error',
      attributes: {
        'telemetry.op': 'agent-error',
        'session.id': `Authorization=Bearer ${BEARER}`,
      },
      body: { message: `failed with ${API_KEY}` },
    }

    const wire = JSON.stringify(ctx.waterfall('session-telemetry/record', record, () => record))
    expect(wire).not.toContain(BEARER)
    expect(wire).not.toContain(API_KEY)
  })

  it('calls next so independently mounted rules still compose', async () => {
    const ctx = await mounted()
    ctx.on('session-telemetry/record', (_record, next) => ({
      ...next(),
      body: { password: 'fixture-password', kept: true },
    }))

    const output = ctx.waterfall('session-telemetry/record', fixture(), () => fixture())
    expect(output.body).toEqual({ password: '[REDACTED]', kept: true })
  })

  it('fails configuration loudly at load', async () => {
    const ctx = new Context()
    await expect(ctx.plugin(Redactor, { replacement: '' })).rejects.toThrow()
  })

  it('throws on over-deep input so the official coordinator withholds that record', async () => {
    const ctx = await mounted()
    let body: Record<string, unknown> = { leaf: 'safe' }
    for (let index = 0; index < 70; index += 1) body = { child: body }
    const record = { ...fixture(), body }

    expect(() => ctx.waterfall('session-telemetry/record', record, () => record))
      .toThrow('maximum nesting depth')
  })
})

